files.chat.jsonata:
(
  $s := $state;
  $t := $action.type;
  $p := $action.payload;
  $add := function($who, $text) {
    $merge([$s, {
      "seq": $s.seq + 1,
      "messages": $append($s.messages, [{"id": "m" & ($s.seq + 1), "who": $who, "text": $text}])
    }])
  };

  $t = "tick" ? (
    $s.phrase != "" ? $merge([$add("moi", $s.phrase), {"phrase": "", "outgoing": $s.phrase, "txN": $s.txN + 1}]) :
    $s.go = "1" ? (
      $txt := $trim($string($s.draft));
      $txt = "" ? $merge([$s, {"go": ""}])
        : $merge([$add("moi", $txt), {"go": "", "draft": "", "outgoing": $txt, "txN": $s.txN + 1}])
    )
  ) :
  $t = "morse:message" ? $add("autre", ($p.speaker ? $string($p.speaker) & " : " : "") & $string($p.text)) :
  $t = "torchError" ? ($s.notice = "" ? $merge([$s, {"notice": "Pas de torche sur cet appareil : réception seule"}]) : $s) :
  $s
)
